x = [1, 2, 3]
y = [3, 5, 9]

def predict(w):
    return [w * xi for xi in x]

def mse(w):
    errors = [p - t for p, t in zip(predict(w), y)]
    return sum(e ** 2 for e in errors) / len(errors)
print(round(mse(2), 2))   # 3.67

